from .common import *
import io

def run():
    cfg={'seed':SEED,'core_studies':['astrocyte_gse330741','mikl_gse173098','moffatt_gse334718','srle'],'labels':'within-parent preferences; positive is toward each assay-defined destination; no cross-assay raw-effect pooling','primary_metric':'equal-study, equal biological-component, equal parent/context/direction normalized selected-candidate regret','models':{'metadata':['metadata','pooled'],'composition':['composition','pooled'],'delta2':['delta2','pooled'],'kmer123':['kmer123','pooled'],'hierarchical':['kmer123','hierarchical'],'meta_shrink':['kmer123','meta'],**{'interaction_'+str(w):['interaction_'+str(w),'pooled'] for w in (3,10,25,50,'full')}},'simple_baselines':['uniform','metadata','composition'],'regularization':.05,'residual_regularization_multiplier':10,'pair_cap_per_context':256,'pair_sampling':'deterministic uniform unordered pairs without replacement, chosen before labels; every pair has an implicit preference and all pairs enter ordering evaluation','preference_ties':'truth ties omitted; prediction ties half credit; lexical candidate ties for selection','weights':'equal study, then connected gene/exact-allele component, then parent-context, then sampled preference','scaler':'training-only weighted mean/std; zero variance scale1','parent_holdout':'three fixed component folds; single-component SRLE ineligible; all same-gene and exact allele matches co-grouped','outer_holdout':'whole study including all cell/reporters/families; purge all held biological components/exact alleles from every training source','windows':[3,10,25,50,'full'],'gate':{'core_studies_required':4,'studies_gain_at_least_0_02_required':3,'macro_regret_gain_min':.02,'leave_best_study_out_gain_min':0.,'max_share_positive_gain_from_one_study':.60,'macro_avoidable_wrong_worsening_max':.02,'any_study_avoidable_wrong_worsening_max':.05,'any_study_regret_worsening_max':.05,'bootstrap_macro_gain_lower_min':-.01,'benchmark':'per held study strongest simple baseline by lowest observed macro regret; ties fewer avoidable failures then lexical; conservative comparator envelope, not a trained model','bootstrap':'5000 Bayesian component bootstrap draws using shared Exponential(1) weights, normalized within each study; one-component studies degenerate; descriptive'},'selection':{'eligible':'must pass every gate component','composite':'macro_regret + 0.25*macro_avoidable_wrong + 0.05*fraction_studies_harmed + 0.10*worst_study_regret','tie':'within1e-12 fewer features, then lexical name','none_pass':'NO-GO; no new dataset discovery; no final generalizable deployment model'},'abstention':{'policy':'accept only if min(selected-candidate desired-sign probability, candidate-set-feasibility probability)>=0.8','thresholds':[0,.5,.6,.7,.8,.9,.95],'threshold_selection':'none; all thresholds fixed now; conditional risk always accompanies coverage','training':'separate L2 logistic direction and feasibility heads, training studies only; rank score alone is not calibrated effect'},'secondary':{'sirloin':'discovery replicate1/2 only, no training in primary study grid','domain':'projection versus nuclear; no outcome-derived reorientation','family':'same endpoint class only; no eligible source for held SRLE within core, report ineligible','pretrained':'frozen cached 3UTRBERT pooled allele delta; restricted two-study Mikl/Moffatt comparison on identical complete-context covered rows; no zero filling or absent-encoder substitution','size_bands':['1','2-3','4-6'],'locality':'span<=6 sensitivity, fixed predictions only; candidate sets must retain >=2 distinct outcomes'},'excluded':'N-zip, TDP EV5, reserved SIRLOIN replicate3/4/NucLibB, reserved Arora/Shukla, unadmitted/corrupted sources','no_new_independent_data_until_gate':True}
    jsave(OUT/'config.json',cfg)
    # Restrict pretrained evaluation to exact certified cache mappings; no unsupported rows filled.
    frame=pd.read_csv(ART/'canonical_interventions.csv',low_memory=False);idx=pd.read_csv(OUT/'model_row_index.csv');frame=frame.set_index('intervention_id').loc[idx.intervention_id].reset_index()
    manifest=readj(ROOT/'results/mechanism_v2/features/bert_pooled_allele_delta_manifest.json');path=ROOT/manifest['path'];assert sha256(path)==manifest['sha256']
    cache=np.load(path,mmap_mode='r');design=pd.read_csv(ROOT/'results/v4_phaseB/model_interventions.csv.gz');assert not design.duplicated(['dataset','parent_id','mutant_id']).any()
    lookup={(r.dataset,r.parent_sequence,r.mutant_sequence):r.feature_row for r in design.itertuples()}
    mapped=np.array([lookup.get((r.dataset,r.parent_sequence,r.mutant_sequence),-1) for r in frame.itertuples()]);valid=mapped>=0
    complete=frame.assign(covered=valid).groupby('parent_context_id').covered.all();valid &= frame.parent_context_id.map(complete).to_numpy() & frame.dataset.isin(['mikl_gse173098','moffatt_gse334718']).to_numpy()
    selected=np.flatnonzero(valid);buf=io.BytesIO();np.savez_compressed(buf,indices=selected,values=cache[mapped[selected]]);save(ART/'pretrained_covered.npz',buf.getvalue())
    jsave(OUT/'pretrained_admission.json',{'cache':str(path.relative_to(ROOT)),'sha256':manifest['sha256'],'definition':manifest['definition'],'source_design_sha256':sha256(ROOT/'results/v4_phaseB/model_interventions.csv.gz'),'covered_rows':len(selected),'covered_studies':frame.loc[valid].groupby('dataset').size().to_dict(),'universal_four_study_model_eligible':False,'missing_core_studies':['astrocyte_gse330741','srle'],'scope':'restricted two-study secondary comparator after simple models; no training new encoder; no missing-vector fill','provenance_limit':'archived mixed Torch/OpenVINO frozen inference, inherited equivalence limitations; no complete pretrained sequence audit for new studies'})
    print('Configuration written; pretrained complete-context rows',len(selected))
if __name__=='__main__':run()
